CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role); $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text NOT NULL DEFAULT '');
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.sync_editor_identity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id) ON CONFLICT(id) DO NOTHING; IF lower(NEW.email) = 'cembulut1981@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END; $$;
CREATE TRIGGER editor_identity AFTER INSERT OR UPDATE OF email_confirmed_at, email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.sync_editor_identity();
CREATE TABLE public.editorial_posts (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, slug text UNIQUE NOT NULL, title text NOT NULL DEFAULT '', excerpt text NOT NULL DEFAULT '', body text NOT NULL DEFAULT '', category text NOT NULL DEFAULT 'haberler', is_game boolean NOT NULL DEFAULT false, image text NOT NULL DEFAULT '', image_rights_confirmed boolean NOT NULL DEFAULT false, source_url text UNIQUE NOT NULL, source_credit text NOT NULL DEFAULT '', source_text text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'queued', created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, approved_at timestamptz, approved_by uuid, failure text, CONSTRAINT editorial_status CHECK(status IN ('queued','draft','published','rejected','failed')), CONSTRAINT editorial_category CHECK(category IN ('haberler','diziler','muzik')), CONSTRAINT editorial_publication CHECK(status <> 'published' OR (approved_at IS NOT NULL AND approved_by IS NOT NULL AND published_at IS NOT NULL AND image <> '' AND image_rights_confirmed)));
GRANT SELECT ON public.editorial_posts TO anon;
GRANT SELECT, INSERT, UPDATE ON public.editorial_posts TO authenticated;
GRANT ALL ON public.editorial_posts TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.editorial_posts_id_seq TO service_role, authenticated;
ALTER TABLE public.editorial_posts ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_posts ON public.editorial_posts FOR SELECT TO anon, authenticated USING(status = 'published');
CREATE POLICY editor_posts_read ON public.editorial_posts FOR SELECT TO authenticated USING(public.has_role(auth.uid(), 'admin'));
CREATE POLICY editor_posts_insert ON public.editorial_posts FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(), 'admin'));
CREATE POLICY editor_posts_update ON public.editorial_posts FOR UPDATE TO authenticated USING(public.has_role(auth.uid(), 'admin')) WITH CHECK(public.has_role(auth.uid(), 'admin'));
CREATE FUNCTION public.validate_editorial_publication() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.status='published' AND (TG_OP='INSERT' OR OLD.status <> 'published') THEN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Only an editor may approve publication'; END IF; NEW.approved_at=now(); NEW.published_at=now(); NEW.approved_by=auth.uid(); END IF; RETURN NEW; END; $$;
CREATE TRIGGER editorial_publication BEFORE INSERT OR UPDATE ON public.editorial_posts FOR EACH ROW EXECUTE FUNCTION public.validate_editorial_publication();
CREATE TABLE public.editorial_job (id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), enabled boolean NOT NULL DEFAULT true, paused boolean NOT NULL DEFAULT false, pause_kind text, message text, lease_token uuid, lease_until timestamptz, last_discovery_day date, last_run_at timestamptz, last_success_at timestamptz, last_run_count integer NOT NULL DEFAULT 0);
GRANT SELECT, UPDATE ON public.editorial_job TO authenticated;
GRANT ALL ON public.editorial_job TO service_role;
ALTER TABLE public.editorial_job ENABLE ROW LEVEL SECURITY;
CREATE POLICY editor_job_read ON public.editorial_job FOR SELECT TO authenticated USING(public.has_role(auth.uid(), 'admin'));
CREATE POLICY editor_job_update ON public.editorial_job FOR UPDATE TO authenticated USING(public.has_role(auth.uid(), 'admin')) WITH CHECK(public.has_role(auth.uid(), 'admin'));
CREATE FUNCTION public.acquire_editorial_lease(_token uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.editorial_job(id) VALUES(1) ON CONFLICT DO NOTHING; UPDATE public.editorial_job SET lease_token=_token, lease_until=now()+interval '5 minutes', last_run_at=now() WHERE id=1 AND enabled AND NOT paused AND (lease_until IS NULL OR lease_until < now()); RETURN FOUND; END; $$;
REVOKE ALL ON FUNCTION public.acquire_editorial_lease(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.acquire_editorial_lease(uuid) TO service_role;